# Arena - Medium sized combat arena with cover
name Arena
dimensions 40.0 10.0 40.0

# Main floor - thick to prevent phasing
block 0.0 -1.0 0.0 40.0 2.0 40.0 0 1 0

# Corner platforms - red team color
block -15.0 0.0 -15.0 6.0 1.0 6.0 2 1 1
block 15.0 0.0 15.0 6.0 1.0 6.0 2 1 1

# Cover pillars - center color
block -10.0 -0.5 -10.0 2.0 1.0 2.0 4 1 1
block 10.0 -0.5 10.0 2.0 1.0 2.0 4 1 1
block -10.0 -0.5 10.0 2.0 1.0 2.0 4 1 1
block 10.0 -0.5 -10.0 2.0 1.0 2.0 4 1 1

# Center elevated platform
block 0.0 1.0 0.0 8.0 0.5 8.0 3 1 1

# Ramps to center
block -6.0 0.5 0.0 4.0 0.3 2.0 1 1 1
block 6.0 0.5 0.0 4.0 0.3 2.0 1 1 1
block 0.0 0.5 -6.0 2.0 0.3 4.0 1 1 1
block 0.0 0.5 6.0 2.0 0.3 4.0 1 1 1

# Side cover walls
block -18.0 1.0 0.0 2.0 2.0 8.0 1 1 1
block 18.0 1.0 0.0 2.0 2.0 8.0 1 1 1
block 0.0 1.0 -18.0 8.0 2.0 2.0 1 1 1
block 0.0 1.0 18.0 8.0 2.0 2.0 1 1 1

# Small jump pads/platforms
block -8.0 0.0 0.0 2.0 0.2 2.0 5 1 1
block 8.0 0.0 0.0 2.0 0.2 2.0 5 1 1
block 0.0 0.0 -8.0 2.0 0.2 2.0 5 1 1
block 0.0 0.0 8.0 2.0 0.2 2.0 5 1 1

# Arena boundaries - outer walls
block 0.0 2.0 20.0 42.0 4.0 1.0 6 1 1
block 0.0 2.0 -20.0 42.0 4.0 1.0 6 1 1
block 20.0 2.0 0.0 1.0 4.0 42.0 6 1 1
block -20.0 2.0 0.0 1.0 4.0 42.0 6 1 1
